-- 资产归属独立于创建时部门；历史个人资源不自动移交，公共池保持平台归属。
SET NAMES utf8mb4;
SET @space_tbl := 'gmd_faq_agent_definition';
SET @space_exists := (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @space_tbl);
SET @space_add := @space_exists > 0 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @space_tbl AND COLUMN_NAME = 'ownership_type') = 0;
SET @space_sql := IF(@space_add, CONCAT('ALTER TABLE `', @space_tbl, '` ADD COLUMN `ownership_type` varchar(20) NOT NULL DEFAULT ''PERSONAL'' COMMENT ''资产归属 PERSONAL/DEPARTMENT/PLATFORM'''), 'SELECT 1');
PREPARE space_stmt FROM @space_sql; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
SET @space_sql := IF(@space_add, CONCAT('UPDATE `', @space_tbl, '` SET ownership_type = ''PLATFORM'' WHERE owner_id IS NULL'), 'SELECT 1');
PREPARE space_stmt FROM @space_sql; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
SET @space_add := @space_exists > 0 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @space_tbl AND COLUMN_NAME = 'owning_dept_id') = 0;
SET @space_sql := IF(@space_add, CONCAT('ALTER TABLE `', @space_tbl, '` ADD COLUMN `owning_dept_id` bigint DEFAULT NULL COMMENT ''资产所属部门，与创建时部门独立'''), 'SELECT 1');
PREPARE space_stmt FROM @space_sql; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
SET @space_add := @space_exists > 0 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @space_tbl AND COLUMN_NAME = 'maintainer_id') = 0;
SET @space_sql := IF(@space_add, CONCAT('ALTER TABLE `', @space_tbl, '` ADD COLUMN `maintainer_id` bigint DEFAULT NULL COMMENT ''指定维护人'''), 'SELECT 1');
PREPARE space_stmt FROM @space_sql; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
SET @space_sql := IF(@space_exists > 0 AND (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @space_tbl AND INDEX_NAME = 'idx_resource_space') = 0, CONCAT('ALTER TABLE `', @space_tbl, '` ADD INDEX `idx_resource_space` (`tenant_id`, `ownership_type`, `owning_dept_id`)'), 'SELECT 1');
PREPARE space_stmt FROM @space_sql; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;

